package br.com.saqz.groups.adapter.output.jdbc.finance

import br.com.saqz.groups.adapter.output.jdbc.transaction.JdbcTransactionRunner
import br.com.saqz.groups.application.finance.charge.*
import br.com.saqz.groups.domain.finance.charge.*
import br.com.saqz.groups.testing.*
import br.com.saqz.postgrestesting.TestPostgres
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.TestInstance
import org.springframework.jdbc.datasource.DriverManagerDataSource
import java.sql.Connection
import java.time.*
import java.util.UUID
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertFailsWith
import kotlin.test.assertIs
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertSame
import kotlin.test.assertTrue

@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class JdbcChargeTransactionRepositoryIntegrationTest{
    private lateinit var dataSource:DriverManagerDataSource
    @BeforeEach fun reset(){dataSource=TestPostgres.migrated(*allGroupFeatureMigrationLocations(),owner=this).dataSource}
    @Test fun `confirmed paid game persists one pending charge and audit`(){val f=fixture();val charge=f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner);assertNotNull(charge);assertEquals(1,count("group_charges"));assertEquals(1,count("group_charge_events"));assertEquals("PENDING",string("SELECT status FROM group_charges"))}
    @Test fun `confirmation replay is equivalent without duplicate audit`(){val f=fixture();val first=f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner);val second=f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner);assertEquals(first?.id,second?.id);assertEquals(1,count("group_charges"));assertEquals(1,count("group_charge_events"))}
    @Test fun `waitlisted attendance stores no charge`(){val f=fixture();assertNull(f.service.attendance(f.game(AttendanceBillingOutcome.WAITLISTED),f.owner));assertEquals(0,count("group_charges"))}
    @Test fun `promotion creates same unique game identity`(){val f=fixture();f.service.attendance(f.game(AttendanceBillingOutcome.PROMOTED),f.owner);f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner);assertEquals(1,count("group_charges"))}
    @Test fun `withdrawal leaves existing pending charge`(){val f=fixture();f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner);assertNull(f.service.attendance(f.game(AttendanceBillingOutcome.WITHDRAWN),f.owner));assertEquals("PENDING",string("SELECT status FROM group_charges"))}
    @Test fun `game cancellation cancels pending and appends event`(){val f=fixture();f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner);f.service.cancelGame(f.group,f.game,f.owner);assertEquals("CANCELLED",string("SELECT status FROM group_charges"));assertEquals(2,count("group_charge_events"))}
    @Test fun `game cancellation flags paid and waived for review`(){val f=fixture();f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner);execute("UPDATE group_charges SET status='PAID' ");f.service.cancelGame(f.group,f.game,f.owner);assertTrue(boolean("SELECT review_required FROM group_charges"));assertTrue(boolean("SELECT finance_review_required FROM games WHERE id='${f.game}'"));assertEquals("PAID",string("SELECT status FROM group_charges"))}
    @Test fun `monthly generation creates selected active members only`(){val f=fixture();val result=assertIs<MonthlyGenerationResult.Success>(f.service.generate(f.monthly(setOf(f.member))));assertEquals(listOf(f.member),result.charges.map{it.memberId});assertEquals(1,count("group_charges"));assertEquals(3000,int("SELECT amount_cents FROM group_charges"))}
    @Test fun `monthly retry never rewrites original amount`(){val f=fixture();val first=assertIs<MonthlyGenerationResult.Success>(f.service.generate(f.monthly(setOf(f.member),3000))).charges.single();val retry=assertIs<MonthlyGenerationResult.Success>(f.service.generate(f.monthly(setOf(f.member),9000))).charges.single();assertEquals(first.id,retry.id);assertEquals(3000,retry.amountCents);assertEquals(1,count("group_charge_events"))}
    @Test fun `monthly generation excludes an inactive member and reports it`(){val f=fixture();execute("UPDATE group_memberships SET active=false WHERE group_id='${f.group}' AND user_id='${f.member}'");val result=assertIs<MonthlyGenerationResult.Success>(f.service.generate(f.monthly(setOf(f.member))));assertEquals(emptyList(),result.charges);assertEquals(1,result.excludedInactiveCount);assertEquals(0,count("group_charges"))}
    @Test fun `monthly generation keeps an inactive member's existing charge untouched`(){val f=fixture();val first=assertIs<MonthlyGenerationResult.Success>(f.service.generate(f.monthly(setOf(f.member),3000))).charges.single();execute("UPDATE group_memberships SET active=false WHERE group_id='${f.group}' AND user_id='${f.member}'");val retry=assertIs<MonthlyGenerationResult.Success>(f.service.generate(f.monthly(setOf(f.member),9000)));assertEquals(emptyList(),retry.charges);assertEquals(1,retry.excludedInactiveCount);assertEquals("PENDING",string("SELECT status FROM group_charges WHERE id='${first.id}'"));assertEquals(3000,int("SELECT amount_cents FROM group_charges WHERE id='${first.id}'"))}
    @Test fun `charge stores member nickname snapshot at creation`(){val f=fixture();execute("UPDATE access_users SET nickname='Apelido' WHERE id='${f.member}'");f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner);assertEquals("Apelido",string("SELECT member_display_name FROM group_charges"))}
    @Test fun `monthly charge stores member nickname snapshot at creation`(){val f=fixture();execute("UPDATE access_users SET nickname='Apelido' WHERE id='${f.member}'");f.service.generate(f.monthly(setOf(f.member)));assertEquals("Apelido",string("SELECT member_display_name FROM group_charges"))}
    @Test fun `deleted group hides charge usage and rejects charge creation`(){val f=fixture();execute("UPDATE access_groups SET deleted_at=now() WHERE id='${f.group}'");assertSame(MonthlyGenerationResult.Hidden,f.service.generate(f.monthly(setOf(f.member))));assertFailsWith<IllegalStateException>{f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner)};assertEquals(0,count("group_charges"))}
    @Test fun `charge stores member display name snapshot at creation`(){val f=fixture();f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner);assertEquals("User",string("SELECT member_display_name FROM group_charges"))}
    @Test fun `renaming a member changes only future charge snapshots`(){val f=fixture();val first=f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner);execute("UPDATE access_users SET display_name='Renamed' WHERE id='${f.member}'");assertEquals("User",string("SELECT member_display_name FROM group_charges WHERE id='${first!!.id}'"));val secondGame=UUID.randomUUID();execute("INSERT INTO games (id,group_id,title,local_date,local_time,zone_id,starts_at,duration_minutes,confirmation_deadline,venue_name,venue_address,capacity,game_fee_cents,status,created_at,updated_at) VALUES ('$secondGame','${f.group}','Treino 2',DATE '2026-08-19',TIME '19:30','America/Sao_Paulo',TIMESTAMPTZ '2026-08-19 22:30Z',90,TIMESTAMPTZ '2026-08-18 22:30Z','Arena','Rua Central 100',24,2500,'PUBLISHED',now(),now())");f.service.attendance(GameChargeInput(f.group,secondGame,f.member,2500,LocalDate.of(2026,8,20),AttendanceBillingOutcome.CONFIRMED),f.owner);assertEquals("Renamed",string("SELECT member_display_name FROM group_charges WHERE game_id='$secondGame'"))}
    @Test fun `a status update on a charge never rewrites its member display name snapshot`(){val f=fixture();val charge=f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner)!!;execute("UPDATE access_users SET display_name='Renamed' WHERE id='${f.member}'");execute("UPDATE group_charges SET status='PAID',version=version+1 WHERE id='${charge.id}'");assertEquals("User",string("SELECT member_display_name FROM group_charges WHERE id='${charge.id}'"))}
    @Test fun `injected repository failure rolls back charge and audit together`(){val f=fixture();val delegate=JdbcChargeTransactionRepository(dataSource);val failing=object:ChargeTransactionRepository by delegate{override fun createGameCharge(input:GameChargeInput,actorId:UUID,now:Instant):Charge{delegate.createGameCharge(input,actorId,now);error("injected")}};val service=ChargeTransactions(JdbcTransactionRunner(dataSource),failing){NOW};assertFailsWith<IllegalStateException>{service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner)};assertEquals(0,count("group_charges"));assertEquals(0,count("group_charge_events"))}

    @Test fun `monthly retry projects the receipt method of an already paid charge`(){val f=fixture();val first=assertIs<MonthlyGenerationResult.Success>(f.service.generate(f.monthly(setOf(f.member),3000))).charges.single();assertIs<ChargeStatusResult.Success>(management().status(f.owner,f.group,first.id,1,ChargeStatusCommand(ChargeStatus.PAID,paidMethod=PaidMethod.CASH)));val retry=assertIs<MonthlyGenerationResult.Success>(f.service.generate(f.monthly(setOf(f.member),9000))).charges.single();assertEquals(first.id,retry.id);assertEquals(PaidMethod.CASH,retry.paidMethod);assertEquals(ChargeStatus.PAID,retry.status)}
    @Test fun `manual receipt persists how the charge was received`(){val f=fixture();val charge=assertNotNull(f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner));assertIs<ChargeStatusResult.Success>(management().status(f.owner,f.group,charge.id,1,ChargeStatusCommand(ChargeStatus.PAID,paidMethod=PaidMethod.CASH)));assertEquals("CASH",string("SELECT paid_method FROM group_charges"));assertEquals(PaidMethod.CASH,management().listOrganizer(f.owner,f.group).let{assertIs<ChargeListResult.Success>(it)}.charges.single().charge.paidMethod)}
    @Test fun `pending and waived charges carry no payment method`(){val f=fixture();val charge=assertNotNull(f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner));assertNull(string("SELECT paid_method FROM group_charges"));assertIs<ChargeStatusResult.Success>(management().status(f.owner,f.group,charge.id,1,ChargeStatusCommand(ChargeStatus.WAIVED)));assertNull(string("SELECT paid_method FROM group_charges"))}
    @Test fun `only the declined with a pending game charge is marked as withdrew`(){val f=fixture();assertNotNull(f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner));attendance(f,"CONFIRMED");assertFalse(withdrew(f));attendance(f,"DECLINED");assertTrue(withdrew(f));attendance(f,"CONFIRMED");assertFalse(withdrew(f))}
    @Test fun `a monthly charge is never marked as withdrew`(){val f=fixture();assertIs<MonthlyGenerationResult.Success>(f.service.generate(f.monthly(setOf(f.member))));attendance(f,"DECLINED");assertFalse(withdrew(f))}
    @Test fun `a declined guest with a pending charge is marked on the guest charge`(){val f=fixture();attendance(f,"CONFIRMED",guestSeq=1);val guest=assertNotNull(f.service.attendance(GameChargeInput(f.group,f.game,f.member,2500,LocalDate.of(2026,8,10),AttendanceBillingOutcome.CONFIRMED,guestSeq=1),f.owner));attendance(f,"DECLINED",guestSeq=1);val rows=assertIs<ChargeListResult.Success>(management().listOrganizer(f.owner,f.group)).charges;assertTrue(rows.single{it.charge.id==guest.id}.charge.withdrew)}
    @Test fun `receiving a withdrawn charge clears the mark`(){val f=fixture();val charge=assertNotNull(f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner));attendance(f,"DECLINED");assertTrue(withdrew(f));assertIs<ChargeStatusResult.Success>(management().status(f.owner,f.group,charge.id,1,ChargeStatusCommand(ChargeStatus.PAID,paidMethod=PaidMethod.CASH)));assertFalse(withdrew(f))}
    @Test fun `waiving a withdrawn charge records the event clears the mark and queues no notice`(){val f=fixture();val charge=assertNotNull(f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner));attendance(f,"DECLINED");val pushBefore=count("notification_push_queue");val whatsappBefore=count("notification_whatsapp_queue");val groupNotices=count("group_notifications");val result=assertIs<ChargeStatusResult.Success>(management().status(f.owner,f.group,charge.id,1,ChargeStatusCommand(ChargeStatus.WAIVED)));assertEquals(ChargeStatus.WAIVED,result.value.charge.status);assertEquals(2,result.value.charge.version);assertEquals("WAIVED",string("SELECT status FROM group_charges"));assertEquals(1,count("group_charge_events WHERE new_status='WAIVED' AND old_status='PENDING'"));assertFalse(withdrew(f));assertEquals(pushBefore,count("notification_push_queue"));assertEquals(whatsappBefore,count("notification_whatsapp_queue"));assertEquals(groupNotices,count("group_notifications"))}
    @Test fun `repeating the waive with the same version does not waive twice`(){val f=fixture();val charge=assertNotNull(f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner));attendance(f,"DECLINED");assertIs<ChargeStatusResult.Success>(management().status(f.owner,f.group,charge.id,1,ChargeStatusCommand(ChargeStatus.WAIVED)));assertSame(ChargeStatusResult.Conflict,management().status(f.owner,f.group,charge.id,1,ChargeStatusCommand(ChargeStatus.WAIVED)));assertEquals(1,count("group_charge_events WHERE new_status='WAIVED'"))}
    @Test fun `an athlete cannot waive a withdrawn charge`(){val f=fixture();val charge=assertNotNull(f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner));attendance(f,"DECLINED");assertSame(ChargeStatusResult.Forbidden,management().status(f.member,f.group,charge.id,1,ChargeStatusCommand(ChargeStatus.WAIVED)));assertEquals("PENDING",string("SELECT status FROM group_charges"));assertTrue(withdrew(f))}
    @Test fun `a charge with an electronic order is not offered for waiving`(){val f=fixture();assertNotNull(f.service.attendance(f.game(AttendanceBillingOutcome.CONFIRMED),f.owner));attendance(f,"DECLINED");execute("UPDATE group_charges SET electronic_order_id='${UUID.randomUUID()}'");assertFalse(withdrew(f))}
    private fun attendance(f:Fixture,status:String,guestSeq:Int=0){execute("INSERT INTO game_attendance (game_id,group_id,member_user_id,guest_seq,status,responded_at,updated_at,member_display_name) VALUES ('${f.game}','${f.group}','${f.member}',$guestSeq,'$status',now(),now(),'User') ON CONFLICT (game_id,member_user_id,guest_seq) DO UPDATE SET status=EXCLUDED.status")}
    private fun withdrew(f:Fixture)=assertIs<ChargeListResult.Success>(management().listOrganizer(f.owner,f.group)).charges.single().charge.withdrew
    private fun management()=ChargeManagement(JdbcTransactionRunner(dataSource),JdbcChargeManagementRepository(dataSource),{NOW}){UUID.randomUUID()}
    private fun fixture():Fixture{val owner=user("owner");val member=user("member");val group=UUID.randomUUID();execute("INSERT INTO access_groups (id,owner_user_id,creation_key,name,time_zone,profile_status,modality,composition,created_at,updated_at) VALUES ('$group','$owner','${UUID.randomUUID()}','Group','America/Sao_Paulo','COMPLETE','COURT_VOLLEYBALL','MIXED',now(),now())");execute("INSERT INTO group_memberships (group_id,user_id,role,created_at,updated_at) VALUES ('$group','$member','ATHLETE',now(),now())");val game=UUID.randomUUID();execute("INSERT INTO games (id,group_id,title,local_date,local_time,zone_id,starts_at,duration_minutes,confirmation_deadline,venue_name,venue_address,capacity,game_fee_cents,status,created_at,updated_at) VALUES ('$game','$group','Treino',DATE '2026-08-12',TIME '19:30','America/Sao_Paulo',TIMESTAMPTZ '2026-08-12 22:30Z',90,TIMESTAMPTZ '2026-08-11 22:30Z','Arena','Rua Central 100',24,2500,'PUBLISHED',now(),now())");return Fixture(owner,member,group,game,ChargeTransactions(JdbcTransactionRunner(dataSource),JdbcChargeTransactionRepository(dataSource)){NOW})}
    private fun user(subject:String):UUID{val id=UUID.randomUUID();execute("INSERT INTO access_users (id,firebase_subject,email_verified,display_name,created_at,updated_at) VALUES ('$id','$subject-${UUID.randomUUID()}',true,'User',now(),now())");return id}
    private data class Fixture(val owner:UUID,val member:UUID,val group:UUID,val game:UUID,val service:ChargeTransactions){fun game(outcome:AttendanceBillingOutcome)=GameChargeInput(group,game,member,2500,LocalDate.of(2026,8,10),outcome);fun monthly(members:Set<UUID>,amount:Long=3000)=MonthlyGenerationCommand(UUID.randomUUID(),group,owner,YearMonth.of(2026,8),amount,LocalDate.of(2026,8,10),members)}
    private fun execute(sql:String){dataSource.connection.use{c->c.createStatement().use{it.execute(sql)}}};private fun count(table:String)=int("SELECT count(*) FROM $table");private fun int(sql:String)=query(sql){it.getInt(1)};private fun string(sql:String)=query(sql){it.getString(1)};private fun boolean(sql:String)=query(sql){it.getBoolean(1)};private fun<T> query(sql:String,read:(java.sql.ResultSet)->T):T=dataSource.connection.use{c->c.createStatement().use{s->s.executeQuery(sql).use{r->check(r.next());read(r)}}}
    private companion object{val NOW:Instant=Instant.parse("2026-08-01T10:00:00Z")}
}
